func letterCombinations(digits string) []string {
	if digits == "" {
		return []string{}
	}
	phone := []string{"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"}
	res, path := []string{}, []byte{}
	var dfs func(i int)
	dfs = func(i int) {
		if i == len(digits) {
			res = append(res, string(path))
			return
		}
		for _, ch := range []byte(phone[digits[i]-'0']) {
			path = append(path, ch) // 选
			dfs(i + 1)              // 往下
			path = path[:len(path)-1] // 撤销
		}
	}
	dfs(0)
	return res
}

