class Solution {
    public List<String> letterCombinations(String digits) {
        if (digits.isEmpty()) {
            return new ArrayList<>();
        }
        String[] phone = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        List<String> combos = new ArrayList<>(List.of(""));     // 一开始只有一个空前缀
        for (char d : digits.toCharArray()) {
            List<String> next = new ArrayList<>();
            for (String c : combos) {
                for (char ch : phone[d - '0'].toCharArray()) {
                    next.add(c + ch);                   // 每个前缀后面接上这一位的每个字母
                }
            }
            combos = next;
        }
        return combos;
    }
}

